-- Configurable director interview/positioning forms and menu wiring.
-- Depends on V129 dictionaries. Repeatable; only adds missing schema/data and does not rewrite published business snapshots.
SET @schema_name = DATABASE();

CREATE TABLE IF NOT EXISTS `zsjos_director_form_template` (
  `id` bigint NOT NULL AUTO_INCREMENT, `scene` varchar(32) NOT NULL, `template_code` varchar(64) NOT NULL,
  `name` varchar(100) NOT NULL, `default_template` bit(1) NOT NULL DEFAULT b'0', `status` varchar(24) NOT NULL,
  `published_version_id` bigint DEFAULT NULL, `version` int NOT NULL DEFAULT 0,
  `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `uk_tenant_scene_code` (`tenant_id`,`scene`,`template_code`,`deleted`),
  KEY `idx_tenant_scene_default` (`tenant_id`,`scene`,`default_template`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='编导业务表单模板';

CREATE TABLE IF NOT EXISTS `zsjos_director_form_template_version` (
  `id` bigint NOT NULL AUTO_INCREMENT, `template_id` bigint NOT NULL, `version_no` int NOT NULL,
  `status` varchar(24) NOT NULL, `fields_json` json NOT NULL, `published_by_user_id` bigint DEFAULT NULL,
  `published_at` datetime DEFAULT NULL, `version` int NOT NULL DEFAULT 0,
  `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `uk_tenant_template_version` (`tenant_id`,`template_id`,`version_no`,`deleted`),
  KEY `idx_tenant_template_status` (`tenant_id`,`template_id`,`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='编导业务表单模板版本';

CREATE TABLE IF NOT EXISTS `zsjos_director_config` (
  `id` bigint NOT NULL AUTO_INCREMENT, `interview_appointment_hours` int NOT NULL DEFAULT 96,
  `positioning_due_hours` int NOT NULL DEFAULT 48, `trial_days` int NOT NULL DEFAULT 14, `version` int NOT NULL DEFAULT 0,
  `creator` varchar(64) DEFAULT '', `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updater` varchar(64) DEFAULT '', `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted` bit(1) NOT NULL DEFAULT b'0', `tenant_id` bigint NOT NULL,
  PRIMARY KEY (`id`), UNIQUE KEY `uk_tenant_director_config` (`tenant_id`,`deleted`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='编导时效配置';

SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='zsjos_positioning_card' AND column_name='service_relation_id')=0,'ALTER TABLE `zsjos_positioning_card` ADD COLUMN `service_relation_id` bigint DEFAULT NULL AFTER `student_person_id`','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='zsjos_positioning_card' AND column_name='operator_user_id')=0,'ALTER TABLE `zsjos_positioning_card` ADD COLUMN `operator_user_id` bigint DEFAULT NULL AFTER `director_user_id`','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='zsjos_positioning_card' AND column_name='template_id')=0,'ALTER TABLE `zsjos_positioning_card` ADD COLUMN `template_id` bigint DEFAULT NULL AFTER `operator_user_id`','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='zsjos_positioning_card' AND column_name='template_version_id')=0,'ALTER TABLE `zsjos_positioning_card` ADD COLUMN `template_version_id` bigint DEFAULT NULL AFTER `template_id`','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='zsjos_positioning_card' AND column_name='fields_snapshot_json')=0,'ALTER TABLE `zsjos_positioning_card` ADD COLUMN `fields_snapshot_json` json DEFAULT NULL AFTER `template_version_id`','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='zsjos_positioning_card' AND column_name='values_snapshot_json')=0,'ALTER TABLE `zsjos_positioning_card` ADD COLUMN `values_snapshot_json` json DEFAULT NULL AFTER `fields_snapshot_json`','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='zsjos_positioning_card' AND column_name='dict_snapshot_json')=0,'ALTER TABLE `zsjos_positioning_card` ADD COLUMN `dict_snapshot_json` json DEFAULT NULL AFTER `values_snapshot_json`','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=@schema_name AND table_name='zsjos_positioning_card' AND column_name='trial_end_date')=0,'ALTER TABLE `zsjos_positioning_card` ADD COLUMN `trial_end_date` date DEFAULT NULL AFTER `dict_snapshot_json`','SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

INSERT INTO `zsjos_director_config` (`interview_appointment_hours`,`positioning_due_hours`,`trial_days`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`)
SELECT 96,48,14,0,'V130',NOW(),'V130',NOW(),b'0',t.id FROM `system_tenant` t
WHERE t.deleted=b'0' AND NOT EXISTS (SELECT 1 FROM `zsjos_director_config` c WHERE c.tenant_id=t.id AND c.deleted=b'0');

