INSERT INTO `zsjos_director_form_template` (`scene`,`template_code`,`name`,`default_template`,`status`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`)
SELECT 'director_interview','default_interview','默认采访表单',b'1','enabled',0,'V130',NOW(),'V130',NOW(),b'0',t.id FROM `system_tenant` t WHERE t.deleted=b'0' AND NOT EXISTS (SELECT 1 FROM `zsjos_director_form_template` x WHERE x.tenant_id=t.id AND x.scene='director_interview' AND x.template_code='default_interview' AND x.deleted=b'0');
INSERT INTO `zsjos_director_form_template` (`scene`,`template_code`,`name`,`default_template`,`status`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`)
SELECT 'positioning_card','default_positioning','默认定位卡',b'1','enabled',0,'V130',NOW(),'V130',NOW(),b'0',t.id FROM `system_tenant` t WHERE t.deleted=b'0' AND NOT EXISTS (SELECT 1 FROM `zsjos_director_form_template` x WHERE x.tenant_id=t.id AND x.scene='positioning_card' AND x.template_code='default_positioning' AND x.deleted=b'0');
INSERT INTO `zsjos_director_form_template_version` (`template_id`,`version_no`,`status`,`fields_json`,`published_at`,`version`,`creator`,`create_time`,`updater`,`update_time`,`deleted`,`tenant_id`)
SELECT t.id,1,'published',IF(t.scene='director_interview',CAST(@interview_fields AS JSON),CAST(@positioning_fields AS JSON)),NOW(),0,'V130',NOW(),'V130',NOW(),b'0',t.tenant_id FROM `zsjos_director_form_template` t WHERE t.template_code IN ('default_interview','default_positioning') AND t.deleted=b'0' AND NOT EXISTS (SELECT 1 FROM `zsjos_director_form_template_version` v WHERE v.tenant_id=t.tenant_id AND v.template_id=t.id AND v.version_no=1 AND v.deleted=b'0');
UPDATE `zsjos_director_form_template` t JOIN `zsjos_director_form_template_version` v ON v.template_id=t.id AND v.version_no=1 AND v.deleted=b'0' SET t.published_version_id=v.id WHERE t.published_version_id IS NULL AND t.template_code IN ('default_interview','default_positioning');

